	 */
	/* @Override */
	public void connectionStateChanged(object adapter) {
		lock (serverAdapter) {
			if (!serverAdapter.isConnected()) {
				disconnect(serverAdapter.hadUnexpectedDisconnect(), true);
			}
			else {
