	/**
	 * Attempt to connect to the server.
	 * @throws RepositoryNotFoundException if named repository does not exist
	 * @throws IOException if IO error occurs
	 */
	public void connect()
    {
		lock (serverAdapter) {
			if (repository != null) {
				try {
					repository.getName(); // just called to test the connection.
				}
				catch (Exception e) when (e is NotConnectedException or RemoteException) {
					if (recoverConnection(e)) {
						return;
					}
					throw e;
				}
			}
			if (repository == null) {
				serverAdapter.connect(); // may cause auto-reconnect of repository
			}
			if (repository == null && serverAdapter.isConnected()) {
				repository = serverAdapter.getRepositoryHandle(name);
				unexpectedDisconnect = false;
				if (repository == null) {
					noSuchRepository = true;
					throw new RepositoryNotFoundException("Repository '" + name + "': not found");
				}
				Msg.info(this, "Connected to repository '" + name + "'");
				changeDispatcher.start();
				fireStateChanged();
			}
		}
	}

	/**
	 * Event reader for change dispatcher.
	 * @return events
	 * @throws InterruptedIOException if repository handle is closed
	 */
	RepositoryChangeEvent[] getEvents()
    {
		RepositoryHandle handle;
		lock (serverAdapter) {
			// Be careful with synchronization since getEvents will block
			// until an event occurs
			if (repository == null) {
				throw new InterruptedIOException();
			}
			handle = repository;
		}
		try {
			return handle.getEvents();
		}
		catch (Exception e) when (e is NotConnectedException or RemoteException) {
			// Initiate recover - dispatcher will be restarted
			recoverConnection(e);
			throw new InterruptedIOException();
		}
		catch (IOException e) {
			lock (serverAdapter) {
				if (!Thread.currentThread().isInterrupted()) {
					serverAdapter.verifyConnection();
					disconnect(true, true);
				}
			}
			throw new InterruptedIOException();
		}
	}

