			checkRepository();
			try {
				return repository.getLength(parentPath, itemName);
			}
			catch (Exception e) when (e is NotConnectedException or RemoteException) {
				if (recoverConnection(e)) {
					return repository.getLength(parentPath, itemName);
				}
				throw e;
			}
		}
	}

